	"google.golang.org/api/option"
)

func main() {
	app := fiber.New()

	saPath := "<PATH_TO_SERVICE_ACCOUNT_JSON_FILE>" // Replace with the path to your Firebase service account JSON file.
	opt := option.WithCredentialsFile(saPath)
	ctx := context.Background()
	app, err := firebase.NewApp(ctx, nil, opt)
	if err != nil {
		log.Fatalf("error initializing app: %v\n", err)
	}

	authClient, err := app.Auth(ctx)
	if err != nil {
		log.Fatalf("error getting Auth client: %v\n", err)
	}

	app.Post("/signup", func(c *fiber.Ctx) error {
		var body struct {
			Email    string `json:"email"`
			Password string `json:"password"`
		}

		c.BodyParser(&body)
		userRecord, err := authClient.CreateUser(ctx, (&firebase.UserToCreate{}).Email(body.Email).Password(body.Password))
		if err != nil {
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{"error": err.Error()})
		}

		return c.JSON(fiber.Map{"uid": userRecord.UID})
	})

	app.Post("/login", func(c *fiber.Ctx) error {
		var body struct {
			Email    string `json:"email"`
			Password string `json:"password"`
		}

		c.BodyParser(&body)
		userRecord, err := authClient.GetUserByEmail(ctx, body.Email)
		if err != nil {
			return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{"error": err.Error()})
		}

		return c.JSON(fiber.Map{"uid": userRecord.UID})
	})

	app.Listen(":3000")
}
