    this.having = (num) => {
      return this.has(num);
    };
    this.each = (callback) => {
      for(let i = 0; i < this.currentThingCount; i++) {
        const thing = new Thing(this.currentThingName);
        this.currentThingArr.push(thing);
        callback(thing);
      }
      return this;
    };
    this.being_the = (attrValue) => {
      this.currentThingArr.forEach(thing => {
        thing[attrValue.attr] = attrValue.value;
      });
      return this;
    };
    this.and_the = (attrValue) => {
      return this.being_the(attrValue);
    };
    this.is_the = (value) => {
      this[value.attr] = value.value;
      return this;
    };
    this.can = (methodName, callback) => {
      if(typeof methodName === 'function') {
        this[methodName.name] = methodName.bind(this);
      } else {
        this[methodName] = callback.bind(this);
        this[methodName + 'Results'] = [];
      }
      return this;
    };
