  get is_a_woman() {
    return this.is_a.woman ? true : false;
  }
  get is_a_man() {
    return this.is_a.man ? true : false;
  }
  is_not_a_a(attr) {
    const isNotA = `is_not_a_${attr}`;
    return this[isNotA] ? true : false;
  }
  is_a_a(attr) {
    const isA = `is_a_${attr}`;
    return this[isA] ? true : false;
  }
  set is_a(targets) {
    if(typeof targets === 'object' && targets !== null) {
      for(let target in targets) {
        this[`is_a_${target}`] = targets[target];
      }
    }
  }
  set is_not_a(targets) {
    if(typeof targets === 'object' && targets !== null) {
      for(let target in targets) {
        this[`is_not_a_${target}`] = targets[target];
